// ============================================================
// trtcClient.js — TRTC Web SDK wrapper
// Tencent Cloud TRTC: no Chinese ID needed, global TURN relay works in China
// UserSig generated client-side (no server needed)
// ============================================================
import TRTC from 'trtc-js-sdk';
import { KJUR } from 'jsrsasign';

// ---- TRTC Config ----
const SDK_APP_ID = 100048996157;
// SecretKey from Tencent Cloud console — embedded here so no server needed
const SECRET_KEY = 'FIDO:/471591623762904706426940426475782025414360449229964613784970673662305541136073779679315900593042307760181166873015351450057386892425878552797682562499330109321447142404';

// Singleton TRTC instance
let trtcClient = null;
let localStream = null;

// ============================================================
// UserSig Generator — runs entirely in the browser (no Buffer/Node.js)
// ============================================================
function strToBytes(str) {
  return new TextEncoder().encode(str);
}

function bytesToBase64UrlSafe(bytes) {
  const str = btoa(String.fromCharCode.apply(null, bytes));
  return str.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function generateUserSig(userId) {
  const sdkAppId = SDK_APP_ID;
  const currentTime = Math.floor(Date.now() / 1000);
  const expireTime = currentTime + 86400; // 24 hours
  const random = Math.floor(Math.random() * 4294967295);

  // Build the official TRTC string-to-sign
  const stringToSign = [
    'TLS.appid_at_3rd',
    'TLS.contenttype',
    'TLS.sdkappid',
    'TLS.ticket',
    'TLS.time',
    'TLS.random',
  ].join('\n') + '\n' + [
    '',
    '',
    String(sdkAppId),
    '',
    String(expireTime),
    String(currentTime),
    String(random),
    String(userId),
    '',
  ].join('\n');

  // HMAC-SHA256 using jsrsasign v11 API
  const hmac = new KJUR.crypto.Mac({ alg: 'HmacSHA256', 'pass': SECRET_KEY });
  hmac.updateString(stringToSign);
  const sigHex = hmac.doFinal().toLowerCase();

  // Build the final UserSig
  const payload = {
    'TLS.account_type': '0',
    'TLS.appid': String(sdkAppId),
    'TLS.expire_after': String(expireTime),
    'TLS.sdkappid': String(sdkAppId),
    'TLS.time': String(currentTime),
    'TLS.userid': String(userId),
    'TLS.version': '2.0',
  };

  const payloadStr = JSON.stringify(payload);
  const payloadBytes = strToBytes(payloadStr);
  const payloadBase64 = bytesToBase64UrlSafe(payloadBytes);
  const sigBase64 = bytesToBase64UrlSafe(strToBytes(sigHex));

  return payloadBase64 + '_' + sigBase64;
}

// ============================================================
// Create TRTC client
// ============================================================
function createTRTCClient(userId, userSig) {
  trtcClient = TRTC.createClient({
    sdkAppId: SDK_APP_ID,
    userId,
    userSig,
    mode: 'rtc',
    // Force Hong Kong region — more accessible from China
    serverRegion: 'ap-guangzhou',
  });
  return trtcClient;
}

// ============================================================
// Join a TRTC room
// ============================================================
export async function joinRoom({ roomId, userId, userName }, callbacks) {
  // Generate UserSig locally — no server needed!
  let userSig;
  try {
    userSig = generateUserSig(userId);
    console.log('[TRTC] UserSig generated for:', userId);
  } catch (err) {
    console.error('[TRTC] UserSig generation failed:', err);
    const msg = err?.message || err?.toString() || String(err);
    callbacks?.onError?.('UserSig error: ' + msg);
    return;
  }

  const client = createTRTCClient(userId, userSig);

  // ---- Local stream ----
  try {
    localStream = TRTC.createStream({
      userId,
      audio: true,
      video: true,
    });
    await localStream.initialize();
    console.log('[TRTC] Local stream initialized');
  } catch (err) {
    console.warn('[TRTC] Camera error, trying audio-only:', err.message);
    try {
      localStream = TRTC.createStream({ userId, audio: true, video: false });
      await localStream.initialize();
    } catch (err2) {
      callbacks?.onError?.('Camera/microphone access denied. Please allow permissions.');
      return;
    }
  }

  // ---- Set up event listeners ----
  client.on(TRTC.EVENT.REMOTE_USER_JOIN, ({ userId: uid }) => {
    console.log('[TRTC] Remote user joined:', uid);
    callbacks?.onPeerJoined?.(uid, uid);
  });

  client.on(TRTC.EVENT.REMOTE_USER_LEAVE, ({ userId: uid }) => {
    console.log('[TRTC] Remote user left:', uid);
    callbacks?.onPeerLeft?.(uid);
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_ADDED, ({ stream }) => {
    const uid = stream.getUserId();
    console.log('[TRTC] Remote stream added:', uid);
    client.subscribe(stream, { audio: true, video: true })
      .then(() => {
        console.log('[TRTC] Subscribed to:', uid);
        callbacks?.onRemoteStream?.(uid, stream);
      })
      .catch(err => console.error('[TRTC] Subscribe failed:', err));
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_REMOVED, ({ stream }) => {
    console.log('[TRTC] Remote stream removed:', stream.getUserId());
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_SUBSCRIBED, ({ stream }) => {
    const uid = stream.getUserId();
    console.log('[TRTC] Remote stream subscribed:', uid);
    callbacks?.onRemoteStream?.(uid, stream);
  });

  client.on(TRTC.EVENT.RTC_ERROR, ({ message }) => {
    console.error('[TRTC] Error:', message);
  });

  client.on(TRTC.EVENT.KICKED_OUT, () => {
    callbacks?.onError?.('You were removed from the room (duplicate login).');
  });

  // ---- Join room ----
  try {
    const numericRoomId = hashRoomId(String(roomId));
    console.log('[TRTC] Joining room:', roomId, '→ numeric:', numericRoomId);

    // Add timeout so join() doesn't hang forever
    const joinPromise = client.join({ roomId: numericRoomId });
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('JOIN_TIMEOUT')), 10000)
    );

    await Promise.race([joinPromise, timeoutPromise]);
    console.log('[TRTC] Joined room successfully!');
    window.__trtcUserId = userId;

    console.log('[TRTC] Publishing local stream...');
    await client.publish(localStream);
    console.log('[TRTC] Local stream published');

    callbacks?.onJoined?.({ roomId, userId });
  } catch (err) {
    console.error('[TRTC] Join/Publish failed:', err.message || err);
    const msg = err?.message || String(err);
    if (msg === 'JOIN_TIMEOUT') {
      callbacks?.onError?.('Cannot reach Tencent TRTC servers. Check your network connection and try again.');
    } else if (msg.includes('6026') || msg.includes('wrong userSig')) {
      callbacks?.onError?.('Login signature invalid. Please refresh and try again.');
    } else if (msg.includes('6003') || msg.includes('room id')) {
      callbacks?.onError?.(`Room "${roomId}" not found or access denied.`);
    } else {
      callbacks?.onError?.('Failed to join room: ' + msg);
    }
    return;
  }
}

// Hash string room ID to 32-bit number for TRTC
function hashRoomId(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash) % 4294967295;
}

// ============================================================
// Leave room
// ============================================================
export async function leaveRoom() {
  if (localStream) {
    try { localStream.stop(); } catch (e) {}
    try { localStream.close(); } catch (e) {}
    localStream = null;
  }

  if (trtcClient) {
    try { await trtcClient.leave(); } catch (e) {}
    trtcClient = null;
  }
}

// ============================================================
// Toggle mic
// ============================================================
export function toggleMic() {
  if (!localStream) return false;
  const audioTrack = localStream.getAudioTrack();
  if (!audioTrack) return false;
  const enabled = !audioTrack.isAudioEnabled();
  audioTrack.setAudioEnabled(enabled);
  return enabled;
}

// ============================================================
// Toggle camera
// ============================================================
export function toggleCamera() {
  if (!localStream) return false;
  const videoTrack = localStream.getVideoTrack();
  if (!videoTrack) return false;
  const enabled = !videoTrack.isVideoEnabled();
  videoTrack.setVideoEnabled(enabled);
  return enabled;
}

// ============================================================
// Get local stream
// ============================================================
export function getLocalStream() {
  return localStream;
}
