function Flashcards({ onBack }) {
  const [category, setCategory] = useState(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const speakWord = (word) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(word);
      utterance.lang = 'en-US';
      utterance.rate = 0.8;
      utterance.pitch = 1.1;
      window.speechSynthesis.speak(utterance);
    }
  };

  const speakSentence = (sentence) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(sentence);
      utterance.lang = 'en-US';
      utterance.rate = 0.7;
      utterance.pitch = 1.1;
      window.speechSynthesis.speak(utterance);
    }
  };

  const nextCard = () => {
    if (!category) return;
    setIsFlipped(false);
    setTimeout(() => {
      setCurrentIndex((prev) => (prev + 1) % FLASHCARDS[category].length);
    }, 200);
  };

  const prevCard = () => {
    if (!category) return;
    setIsFlipped(false);
    setTimeout(() => {
      setCurrentIndex((prev) => (prev - 1 + FLASHCARDS[category].length) % FLASHCARDS[category].length);
    }, 200);
  };

  const resetCard = () => {
    setIsFlipped(false);
    setCurrentIndex(0);
  };

  const selectCategory = (catId) => {
    setCategory(catId);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  const getImageUrl = (word, index) => {
    const seed = `${word}-${index}-${Date.now()}`;
    return `https://picsum.photos/seed/${seed}/400/300`;
  };

  if (!category) {
    return (
      <div style={styles.container}>
        <div style={styles.header}>
          <button style={styles.backButton} onClick={onBack}>
            <Home size={20} /> Home
          </button>
          <h2 style={styles.title}>📚 English Flashcards</h2>
          <p style={styles.subtitle}>Choose a topic to learn!</p>
        </div>
        
        <div style={styles.grid}>
          {CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              style={styles.categoryCard}
              onClick={() => selectCategory(cat.id)}
            >
              <span style={styles.categoryEmoji}>{cat.emoji}</span>
              <span style={styles.categoryName}>{cat.name}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  const cards = FLASHCARDS[category];
  const card = cards[currentIndex];

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <button style={styles.backButton} onClick={() => setCategory(null)}>
          <ArrowLeft size={20} /> Back
        </button>
        <h2 style={styles.title}>{CATEGORIES.find(c => c.id === category)?.emoji} {CATEGORIES.find(c => c.id === category)?.name}</h2>
        <span style={styles.counter}>{currentIndex + 1} / {cards.length}</span>
      </div>

      <div style={styles.cardContainer}>
        <div 
          style={{
            ...styles.card,
            transform: isFlipped ? 'rotateY(180deg)' : 'rotateY(0deg)',
          }}
          onClick={() => setIsFlipped(!isFlipped)}
        >
          {/* Front of card */}
          <div style={styles.cardFront}>
            <img 
              src={getImageUrl(card.word, currentIndex)} 
              alt={card.word}
              style={styles.image}
              onError={(e) => {
                e.target.src = `https://picsum.photos/400/300?random=${currentIndex}`;
              }}
            />
            <div style={styles.wordContainer}>
              <h2 style={styles.word}>{card.word}</h2>
              <button 
                style={styles.speakerButton}
                onClick={(e) => {
                  e.stopPropagation();
                  speakWord(card.word);
                }}
              >
                <Volume2 size={24} />
              </button>
            </div>
            <p style={styles.tapHint}>Tap to flip</p>
          </div>

          {/* Back of card */}
          <div style={styles.cardBack}>
            <div style={styles.sentenceContainer}>
              <p style={styles.sentenceEnglish}>{card.sentence}</p>
              <button 
                style={styles.sentenceSpeaker}
                onClick={(e) => {
                  e.stopPropagation();
                  speakSentence(card.sentence);
                }}
              >
                <Volume2 size={20} /> Listen
              </button>
              <p style={styles.translation}>{card.translation}</p>
            </div>
          </div>
        </div>
      </div>

      <div style={styles.controls}>
        <button style={styles.navButton} onClick={prevCard}>
          <ArrowLeft size={24} />
        </button>
        <button style={styles.resetButton} onClick={resetCard}>
          <RotateCcw size={20} /> Start Over
        </button>
        <button style={styles.navButton} onClick={nextCard}>
          <ArrowRight size={24} />
        </button>
      </div>

      <div style={styles.progressBar}>
        <div 
          style={{
            ...styles.progressFill,
            width: `${((currentIndex + 1) / cards.length) * 100}%`
          }}
        />
      </div>
    </div>
  );
}

